}
.video-suggestion a{ display:inline-block; padding:.25rem 0; }
.video-suggestion small{ display:block; color:var(--928374); }

.web.error-view .right-wrapper{ display:none; }
.web.error-view .left{ width:min(100%, 780px); }
.error-actions{
