  padding-bottom:.3rem;
}

.tabs .tab{
  min-height:2.5rem;
  box-sizing:border-box;
  display:inline-flex;
  align-items:center;
  border-radius:.35rem .35rem 0 0;
}

.filters .filter select,
.filters .filter input{
