@media only screen and (max-width:450px){#images .image-wrapper{width:100%}}
@media only screen and (max-width:1550px){
  .web .right-right,.web .right-left{float:none;width:initial;padding:0 0 0 15px}
  .web .left,.searchbox,#images .infobox{width:60%}
  .web .right-wrapper{width:40%}
}
@media only screen and (max-width:1000px){
  form{padding-top:27px}
  .navigation{left:0;right:unset;line-height:22px}
  .nextpage.img{width:initial}
  .web .right-right,.web .right-left{border:none;padding:0}
  .web .right-wrapper{float:none;padding:0;width:initial}
  .web .left,.searchbox{width:100%}
  body:not(.instances) table td{display:block;width:100%}
  table a{padding:0}
  .web.has-answer .left::before{display:block;content:"Results";font-size:24px;font-weight:bold;margin-bottom:17px;color:var(--bdae93)}
  .web .answer{max-height:200px}
