/* Accessible, touch-friendly result-page chrome. Themes supply colours while
   this layer supplies layout, sizing and focus treatment. */
body:not(.home){
  width:min(100% - 2rem, 1440px);
  max-width:none;
  margin:clamp(.75rem, 2vw, 1.5rem) auto 4rem;
  font-size:clamp(.92rem, .86rem + .18vw, 1rem);
}

.navigation{
  position:static;
  display:flex;
  justify-content:flex-end;
  align-items:center;
  gap:.15rem;
  min-height:2.75rem;
  line-height:normal;
  flex-wrap:wrap;
}

.navigation a{
  display:inline-flex;
  align-items:center;
  min-height:2.5rem;
  padding:0 .6rem;
  border-radius:.35rem;
  text-decoration:none;
}

.navigation a:not(:last-child)::after{ content:none; }
.navigation a:hover{ background:var(--3c3836); text-decoration:none; }

form[role="search"]{
  margin-top:.35rem;
}

.searchbox{
  width:min(100%, 780px);
  height:2.875rem;
  margin-bottom:.55rem;
  border-radius:.45rem;
}

.searchbox input,
.searchbox input[type="text"]{
  min-height:2.875rem;
  line-height:2.875rem;
  font-size:1rem;
}

.searchbox input[type="submit"]{
  min-width:5.5rem;
  text-align:center;
}

.searchbox:focus-within{
  border-color:var(--8ec07c);
  box-shadow:0 0 0 3px color-mix(in srgb, var(--8ec07c) 20%, transparent);
}

.provider-status{
  margin:.15rem 0 .65rem;
  font-size:.76rem;
  color:var(--928374);
  letter-spacing:.03em;
}

.provider-status span{ color:var(--8ec07c); padding:0 .22rem; }

.video-suggestion{
  max-width:780px;
  box-sizing:border-box;
  padding:.8rem 1rem;
  margin:.85rem 0;
  border-left:3px solid var(--8ec07c);
  background:var(--3c3836);
  overflow-wrap:anywhere;
  line-height:1.6;
}
.video-suggestion a{ display:inline-block; padding:.25rem 0; }
.video-suggestion small{ display:block; color:var(--928374); }

.web.error-view .right-wrapper{ display:none; }
.web.error-view .left{ width:min(100%, 780px); }
.error-actions{
  display:flex;
  flex-wrap:wrap;
  gap:.5rem;
  margin:.85rem 0 .5rem;
}
.infobox .error-actions a{
  display:inline-flex;
  align-items:center;
  min-height:2.5rem;
  padding:0 .8rem;
  border:1px solid var(--504945);
  border-radius:.4rem;
  text-decoration:none;
}
.infobox .error-actions a:hover{
  border-color:var(--8ec07c);
  text-decoration:none;
}
.error-note{ margin:.65rem 0 0; color:var(--928374); }

.tabs,
.filters{
  scrollbar-width:thin;
  padding-bottom:.3rem;
}

.tabs .tab{
  min-height:2.5rem;
  box-sizing:border-box;
  display:inline-flex;
  align-items:center;
  border-radius:.35rem .35rem 0 0;
}

.filters .filter select,
.filters .filter input{
  min-height:2rem;
  box-sizing:border-box;
}

.web .left{ width:62%; }
.web .right-wrapper{ width:38%; }
.web .text-result{ margin-bottom:1.8rem; }
.web .text-result .title{ line-height:1.35; }

.web a:focus-visible,
button:focus-visible,
input:focus-visible,
select:focus-visible{
  outline:2px solid var(--8ec07c);
  outline-offset:2px;
}

@media only screen and (max-width:1000px){
  body:not(.home){ width:min(100% - 1.25rem, 900px); }
  form[role="search"]{ padding-top:0; }
  .navigation{ justify-content:flex-start; }
  .web .left,.web .right-wrapper{ width:100%; }
}

@media only screen and (max-width:560px){
  body:not(.home){ width:calc(100% - 1rem); margin-top:.5rem; }
  .navigation{ gap:0; }
  .navigation a{ min-height:2.35rem; padding:0 .45rem; font-size:.82rem; }
  .searchbox input[type="submit"]{ min-width:4.25rem; padding:0 .55rem; }
  .provider-status{ margin-bottom:.45rem; }
  .tabs .tab{ padding:4px .7rem; }
  .filters .filter{ margin-right:.35rem; }
  .thumb-wrap{ width:112px; height:63px; }
  .thumb-wrap.portrait{ width:38px; }
  .thumb-wrap.square{ width:63px; }
  .web .text-result .title{ font-size:1rem; }
}

